using System;using System.Linq;using System.Text.RegularExpressions;using System.Collections.Generic;
namespace BeamScheduleFormatter {
class SlabBar {public int Diameter,ExplicitCount;public double SpacingMm;public string Raw;public static SlabBar Parse(string text){string value=text.Trim();if(Regex.IsMatch(value,@"^-+$"))return null;var m=Regex.Match(value,@"^(?:#|%%[Cc]|Ø)\s*(\d+)\s*@\s*(\d+(?:\.\d+)?)\s*C/C$",RegexOptions.IgnoreCase);if(!m.Success)throw new Exception("Unsupported slab reinforcement: "+text);return new SlabBar{Diameter=int.Parse(m.Groups[1].Value),SpacingMm=double.Parse(m.Groups[2].Value,System.Globalization.CultureInfo.InvariantCulture),Raw=text};}}
class SlabScheduleRow {public string Mark;public double Thickness;public SlabBar[] Bars;public bool Manual;}
static class SlabScheduleReader {
 public static readonly string[] Columns={"Bottom short full","Bottom short curtailed","Bottom long full","Bottom long curtailed","Top over long support continuous","Top over long support end","Top over short support continuous","Top over short support end","Distribution"};
 static string Text(Entity e){return string.Concat(e.P.Where(p=>p.Code==1||p.Code==3).Select(p=>p.Value)).Trim();}
 public static List<SlabScheduleRow> Read(string raw){var drawing=Dxf.Parse(raw);if(drawing.ModelEntities().Any(e=>(e.Type=="TEXT"||e.Type=="MTEXT")&&SlabFormatter.Plain(e)=="SCHEDULE OF SLAB"))return SlabFormatter.ReadRevised(drawing);var text=drawing.ModelEntities().Where(e=>e.Type=="TEXT"||e.Type=="MTEXT").ToList();if(!text.Any(e=>Text(e).ToUpperInvariant().Contains("SLAB SCHEDULE")))throw new Exception("No slab schedule title found.");var full=text.Where(e=>Text(e).Equals("FULL LENGTH",StringComparison.OrdinalIgnoreCase)).OrderBy(e=>e.Num(10)).ToList();if(full.Count!=2)throw new Exception("Expected short/long full-length bottom column headers.");double start=full[0].Num(10),step=(full[1].Num(10)-start)/2;if(step<=0)throw new Exception("Invalid slab column geometry.");var marks=text.Where(e=>Regex.IsMatch(Text(e),@"^S\d+(?:\s*,\s*S\d+)*$",RegexOptions.IgnoreCase)).ToList();var result=new List<SlabScheduleRow>();foreach(var mark in marks){var depth=text.Where(e=>e.Num(10)>mark.Num(10)&&e.Num(10)<start-step/2&&Regex.IsMatch(Text(e),@"^\d+(?:\.\d+)?$")&&Math.Abs(e.Num(20)-mark.Num(20))<step/5).OrderBy(e=>Math.Abs(e.Num(20)-mark.Num(20))).FirstOrDefault();if(depth==null)throw new Exception("Missing thickness for "+Text(mark));double y=depth.Num(20);var bars=new SlabBar[9];for(int c=0;c<9;c++){double x=start+c*step;var cell=text.Where(e=>Math.Abs(e.Num(20)-y)<step/20&&Math.Abs(e.Num(10)-x)<step*.49).ToList();if(cell.Count!=1)throw new Exception("Missing/ambiguous "+Columns[c]+" for "+Text(mark));bars[c]=SlabBar.Parse(Text(cell[0]));}foreach(string name in Text(mark).Split(',')){string key=name.Trim().ToUpperInvariant();if(result.Any(r=>r.Mark==key))throw new Exception("Duplicate slab mark "+key);result.Add(new SlabScheduleRow{Mark=key,Thickness=double.Parse(Text(depth),System.Globalization.CultureInfo.InvariantCulture),Bars=bars});}}if(result.Count==0)throw new Exception("No slab marks found.");return result;}
}
}
